mapper.select:
SELECT 
FROM shop_order_after_sale
WHERE id = #{id}
  AND uid = #{uid}
  AND IFNULL(is_del, 0) = 0
LIMIT 1

SELECT t1.id, t1.service_no AS serviceNo, t1.order_id AS orderId, t1.order_no AS orderNo, t1.uid, t2.real_name AS realName, t2.user_phone AS userPhone, t2.user_address AS userAddress, t1.after_sale_type AS afterSaleType, t1.status, t1.apply_amount AS applyAmount, t1.reason, t1.user_remark AS userRemark, t1.audit_remark AS auditRemark, t1.receive_remark AS receiveRemark, t1.return_express_name AS returnExpressName, t1.return_express_no AS returnExpressNo, t1.return_remark AS returnRemark, t1.audit_time AS auditTime, t1.return_time AS returnTime, t1.receive_time AS receiveTime, t1.refund_time AS refundTime, t1.create_time AS createTime FROM shop_order_after_sale t1 LEFT JOIN shop_order t2 ON t1.order_id = t2.id WHERE IFNULL(t1.is_del, 0) = 0
AND t1.service_no LIKE CONCAT('%', #{dto.serviceNo}, '%')
AND t1.order_no LIKE CONCAT('%', #{dto.orderNo}, '%')
AND t1.after_sale_type = #{dto.afterSaleType}
AND t1.status = #{dto.status}
ORDER BY t1.create_time DESC, t1.id DESC

SELECT 
FROM shop_order_after_sale
WHERE uid = #{uid}
  AND IFNULL(is_del, 0) = 0

    AND order_no = #{orderNo}


    AND service_no = #{serviceNo}

ORDER BY create_time DESC, id DESC

    LIMIT #{limit}
